'use client';

import React, { useEffect, useRef, useState } from 'react';
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { Protocol } from 'pmtiles';
import { pmtilesDiscovery, type DiscoveredTiles } from '@/services/pmtiles-discovery';
// Color utilities are handled by LayerManager;
import { LayerManager } from './LayerManager';
import { Tooltips } from './Tooltips';

// Register PMTiles protocol
  const protocol = new Protocol();
maplibregl.addProtocol('pmtiles', protocol.tile);

export interface PMTilesMapProps {
  className?: string;
  onMapLoad?: (map: maplibregl.Map) => void;
  onMapError?: (error: Error) => void;
}

export interface MapState {
  zoom: number;
  center: [number, number];
  bearing: number;
  pitch: number;
  isLoaded: boolean;
  isLoading: boolean;
  error: string | null;
}

export interface LayerVisibility {
  basemap: boolean;
  kommune: boolean;
  h3: boolean;
  bnbo: boolean;
}

export interface DataMode {
  current: 'total' | 'pfas' | 'diquat' | 'glyphosate';
  year: number;
  availableYears: number[];
}

/**
 * New PMTiles Map Component
 * Clean slate implementation with automatic layer switching based on zoom level
 */
export default function NewPMTilesMap({ 
  className = '',
  onMapLoad,
  onMapError 
}: PMTilesMapProps) {
  const mapContainer = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  
  // State management
  const [mapState, setMapState] = useState<MapState>({
    zoom: 6,
    center: [12.0, 56.0], // Denmark center
    bearing: 0,
    pitch: 0,
    isLoaded: false,
    isLoading: true,
    error: null
  });
  
  const [layerVisibility, setLayerVisibility] = useState<LayerVisibility>({
    basemap: true,
    kommune: false,
    h3: false,
    bnbo: false
  });
  
  const [dataMode, setDataMode] = useState<DataMode>({
    current: 'total',
    year: 2023,
    availableYears: []
  });
  
  const [discoveredTiles, setDiscoveredTiles] = useState<DiscoveredTiles | null>(null);
  const [layerManager, setLayerManager] = useState<LayerManager | null>(null);

  // Initialize map
  useEffect(() => {
    if (!mapContainer.current || mapRef.current) return;

    const map = new maplibregl.Map({
      container: mapContainer.current,
      style: {
        version: 8,
        sources: {},
        layers: []
      },
      center: mapState.center,
      zoom: mapState.zoom,
      bearing: mapState.bearing,
      pitch: mapState.pitch,
      maxZoom: 18,
      minZoom: 4,
      maxBounds: [
        [7.0, 54.0], // Southwest coordinates (Denmark bounds)
        [16.0, 58.0]  // Northeast coordinates
      ]
    });

    mapRef.current = map;

    // Initialize layer manager
    const manager = new LayerManager(map);
    setLayerManager(manager);

    // Map event listeners
    map.on('load', async () => {
      try {
        setMapState(prev => ({ ...prev, isLoading: true }));
        
        // Discover available tiles
        const tiles = await pmtilesDiscovery.discoverAllTiles();
        setDiscoveredTiles(tiles);
        
        // Get available years
        const years = await pmtilesDiscovery.getAvailableYears();
        setDataMode(prev => ({ ...prev, availableYears: years }));
        
        // Initialize basemap
        await manager.initializeBasemap(tiles.basemap);
        
        // Set initial layer visibility based on zoom
        updateLayerVisibility(map.getZoom());
        
        setMapState(prev => ({ 
          ...prev, 
          isLoaded: true, 
          isLoading: false,
          error: null 
        }));
        
        onMapLoad?.(map);
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : 'Unknown error';
        setMapState(prev => ({ 
          ...prev, 
          isLoading: false, 
          error: errorMessage 
        }));
        onMapError?.(error instanceof Error ? error : new Error(errorMessage));
      }
    });

    map.on('zoom', () => {
      const zoom = map.getZoom();
      setMapState(prev => ({ ...prev, zoom }));
      updateLayerVisibility(zoom);
    });

    map.on('move', () => {
      const center = map.getCenter();
      setMapState(prev => ({ 
        ...prev, 
        center: [center.lng, center.lat],
        bearing: map.getBearing(),
        pitch: map.getPitch()
      }));
    });

    map.on('error', (e) => {
      const errorMessage = e.error?.message || 'Map error occurred';
      setMapState(prev => ({ ...prev, error: errorMessage }));
      onMapError?.(e.error || new Error(errorMessage));
    });

    return () => {
      map.remove();
      mapRef.current = null;
    };
  }, [onMapLoad, onMapError]);

  // Update layer visibility based on zoom level
  const updateLayerVisibility = (zoom: number) => {
    const newVisibility: LayerVisibility = {
      basemap: true, // Always visible
      kommune: zoom >= 4 && zoom < 9,
      h3: zoom >= 9,
      bnbo: layerVisibility.bnbo // Maintain user setting
    };

    setLayerVisibility(prev => ({
      ...prev,
      basemap: newVisibility.basemap,
      kommune: newVisibility.kommune,
      h3: newVisibility.h3
      // Don't update bnbo here - it's user controlled
    }));
    
    // Update actual map layers
    if (layerManager && discoveredTiles) {
      layerManager.updateLayerVisibility(newVisibility, {
        dataMode: dataMode.current,
        year: dataMode.year,
        resolution: getH3ResolutionForZoom(zoom)
      });
    }
  };

  // Get appropriate H3 resolution based on zoom level
  const getH3ResolutionForZoom = (zoom: number): number => {
    if (zoom < 9) return 7;
    if (zoom < 12) return 8;
    if (zoom < 14) return 9;
    return 10;
  };

  // Handle data mode change
  const handleDataModeChange = async (mode: 'total' | 'pfas' | 'diquat' | 'glyphosate') => {
    if (!layerManager || !discoveredTiles) return;

    setDataMode(prev => ({ ...prev, current: mode }));
    
    // Update layer styling for new data mode
    await layerManager.updateDataMode(mode, {
      year: dataMode.year,
      resolution: getH3ResolutionForZoom(mapState.zoom)
    });
  };

  // Handle year change
  const handleYearChange = async (year: number) => {
    if (!layerManager || !discoveredTiles) return;

    setDataMode(prev => ({ ...prev, year }));
    
    // Update layers for new year
    await layerManager.updateYear(year, {
      dataMode: dataMode.current,
      resolution: getH3ResolutionForZoom(mapState.zoom)
    });
  };

  // Handle BNBO toggle
  const handleBNBOToggle = (visible: boolean) => {
    setLayerVisibility(prev => ({ ...prev, bnbo: visible }));
    
    if (layerManager && discoveredTiles) {
      layerManager.updateBNBOVisibility(visible, discoveredTiles.bnbo);
    }
  };

  // Render loading state
  if (mapState.isLoading) {
    return (
      <div className={`relative ${className}`}>
        <div className="absolute inset-0 bg-gray-900 flex items-center justify-center">
          <div className="text-white text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-white mx-auto mb-4"></div>
            <p>Loading map data...</p>
          </div>
        </div>
      </div>
    );
  }

  // Render error state
  if (mapState.error) {
    return (
      <div className={`relative ${className}`}>
        <div className="absolute inset-0 bg-red-900 flex items-center justify-center">
          <div className="text-white text-center max-w-md p-4">
            <h3 className="text-xl font-bold mb-2">Map Error</h3>
            <p className="mb-4">{mapState.error}</p>
            <button
              onClick={() => window.location.reload()}
              className="px-4 py-2 bg-red-700 hover:bg-red-600 rounded transition-colors"
            >
              Reload Page
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`relative ${className}`}>
      {/* Map container */}
      <div 
        ref={mapContainer} 
        className="absolute inset-0"
        style={{ width: '100%', height: '100%' }}
      />
      
      {/* Map controls overlay */}
      {mapState.isLoaded && (
        <>
          {/* Data mode selector */}
          <div className="absolute top-4 left-4 z-10">
            <div className="bg-black/80 backdrop-blur-sm rounded-lg p-3">
              <h3 className="text-white text-sm font-medium mb-2">Data Mode</h3>
              <div className="space-y-1">
                {(['total', 'pfas', 'diquat', 'glyphosate'] as const).map((mode) => (
                  <button
                    key={mode}
                    onClick={() => handleDataModeChange(mode)}
                    className={`w-full text-left px-3 py-1 rounded text-sm transition-colors ${
                      dataMode.current === mode
                        ? 'bg-white text-black'
                        : 'text-white hover:bg-white/20'
                    }`}
                  >
                    {mode === 'total' ? 'Total Pesticide' : mode.toUpperCase()}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* Year selector */}
          <div className="absolute top-4 left-48 z-10">
            <div className="bg-black/80 backdrop-blur-sm rounded-lg p-3">
              <h3 className="text-white text-sm font-medium mb-2">Year</h3>
              <select
                value={dataMode.year}
                onChange={(e) => handleYearChange(Number(e.target.value))}
                className="bg-white/20 text-white rounded px-2 py-1 text-sm"
              >
                {dataMode.availableYears.map(year => (
                  <option key={year} value={year} className="text-black">
                    {year}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* BNBO toggle */}
          <div className="absolute top-4 right-4 z-10">
            <div className="bg-black/80 backdrop-blur-sm rounded-lg p-3">
              <label className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  checked={layerVisibility.bnbo}
                  onChange={(e) => handleBNBOToggle(e.target.checked)}
                  className="rounded"
                />
                <span className="text-white text-sm">BNBO Protected Areas</span>
              </label>
            </div>
          </div>

          {/* Zoom level indicator */}
          <div className="absolute bottom-4 left-4 z-10">
            <div className="bg-black/80 backdrop-blur-sm rounded px-2 py-1">
              <span className="text-white text-xs">
                Zoom: {mapState.zoom.toFixed(1)} | 
                {layerVisibility.kommune ? ' Kommune' : ''}
                {layerVisibility.h3 ? ` H3 (res ${getH3ResolutionForZoom(mapState.zoom)})` : ''}
              </span>
            </div>
          </div>

          {/* Tooltips component */}
          {mapRef.current && (
            <Tooltips
              map={mapRef.current}
              layerVisibility={layerVisibility}
              dataMode={dataMode.current}
              year={dataMode.year}
            />
          )}
        </>
      )}
    </div>
  );
} 