/**
 * Color Scaling Utilities
 * Implements data-driven color schemes with transparent zero values and white-to-red gradient
 */

export interface ColorScale {
  stops: Array<[number, string]>;
  domain: [number, number];
  buckets: number;
}

export interface DataStats {
  min: number;
  max: number;
  mean: number;
  median: number;
  percentiles: Record<number, number>;
  nonZeroMin: number;
  nonZeroMax: number;
}

/**
 * Calculate comprehensive statistics for a dataset
 */
export function calculateDataStats(values: number[]): DataStats {
  const nonZeroValues = values.filter(v => v > 0);
  const sortedValues = [...values].sort((a, b) => a - b);
  const sortedNonZeroValues = [...nonZeroValues].sort((a, b) => a - b);

  const percentiles: Record<number, number> = {};
  for (let p = 10; p <= 90; p += 10) {
    const index = Math.floor((p / 100) * (sortedValues.length - 1));
    percentiles[p] = sortedValues[index];
  }

  return {
    min: Math.min(...values),
    max: Math.max(...values),
    mean: values.reduce((sum, v) => sum + v, 0) / values.length,
    median: sortedValues[Math.floor(sortedValues.length / 2)],
    percentiles,
    nonZeroMin: nonZeroValues.length > 0 ? Math.min(...nonZeroValues) : 0,
    nonZeroMax: nonZeroValues.length > 0 ? Math.max(...nonZeroValues) : 0
  };
}

/**
 * Generate decile-based color scale for pesticide data
 */
export function createPesticideColorScale(
  stats: DataStats,
  buckets: number = 10
): ColorScale {
  const stops: Array<[number, string]> = [];
  
  // First stop: transparent for zero values
  stops.push([0, 'rgba(0, 0, 0, 0)']);
  
  // If we have non-zero values, create gradient from white to red
  if (stats.nonZeroMax > 0) {
    const nonZeroValues = [];
    
    // Create synthetic data points for decile calculation
    // This is a simplified approach - in production you'd use actual data
    const step = (stats.nonZeroMax - stats.nonZeroMin) / (buckets - 1);
    for (let i = 0; i < buckets; i++) {
      nonZeroValues.push(stats.nonZeroMin + (step * i));
    }
    
    // Generate white-to-red gradient
    for (let i = 0; i < buckets; i++) {
      const value = nonZeroValues[i];
      const intensity = i / (buckets - 1); // 0 to 1
      
      // White to red gradient
      const red = 255;
      const green = Math.round(255 * (1 - intensity));
      const blue = Math.round(255 * (1 - intensity));
      const alpha = 0.7 + (0.3 * intensity); // Increase opacity with intensity
      
      stops.push([value, `rgba(${red}, ${green}, ${blue}, ${alpha})`]);
    }
  }
  
  return {
    stops,
    domain: [stats.min, stats.max],
    buckets
  };
}

/**
 * Generate color scale for BNBO protected areas
 */
export function createBNBOColorScale(): ColorScale {
  return {
    stops: [
      [0, 'rgba(0, 0, 0, 0)'], // Transparent for no data
      [1, 'rgba(255, 107, 107, 0.8)'], // Action Required - red
      [2, 'rgba(81, 207, 102, 0.8)'], // Completed - green
      [3, 'rgba(134, 142, 150, 0.8)'] // Unknown - gray
    ],
    domain: [0, 3],
    buckets: 4
  };
}

/**
 * Create MapLibre GL JS expression for color scaling
 */
export function createColorExpression(
  colorScale: ColorScale,
  dataField: string
): any[] {
  const expression: any[] = ['case'];
  
  // Add condition for each stop
  for (let i = 0; i < colorScale.stops.length - 1; i++) {
    const [value, color] = colorScale.stops[i];
    const [nextValue] = colorScale.stops[i + 1];
    
    if (i === 0 && value === 0) {
      // Special case for zero values (transparent)
      expression.push(['==', ['get', dataField], 0], color);
    } else {
      // Range condition
      expression.push(
        ['all', ['>=', ['get', dataField], value], ['<', ['get', dataField], nextValue]],
        color
      );
    }
  }
  
  // Add final condition for maximum value
  const [lastValue, lastColor] = colorScale.stops[colorScale.stops.length - 1];
  expression.push(['>=', ['get', dataField], lastValue], lastColor);
  
  // Default fallback
  expression.push('rgba(0, 0, 0, 0)');
  
  return expression;
}

/**
 * Create legend data for color scale
 */
export function createLegendData(
  colorScale: ColorScale,
  unit: string = 'g/ha'
): Array<{ value: number; color: string; label: string }> {
  return colorScale.stops
    .filter(([value]) => value > 0) // Skip transparent zero value
    .map(([value, color]) => ({
      value,
      color,
      label: `${value.toFixed(2)} ${unit}`
    }));
}

/**
 * Get appropriate color scale based on data mode
 */
export function getColorScaleForMode(
  mode: 'total' | 'pfas' | 'diquat' | 'glyphosate',
  h3Stats?: DataStats,
  kommuneStats?: DataStats
): { h3Scale: ColorScale; kommuneScale: ColorScale } {
  // Create separate scales for H3 and Kommune data since they have different value ranges
  const h3Scale = h3Stats ? createPesticideColorScale(h3Stats) : createDefaultColorScale();
  const kommuneScale = kommuneStats ? createPesticideColorScale(kommuneStats) : createDefaultColorScale();
  
  return { h3Scale, kommuneScale };
}

/**
 * Create default color scale when no data is available
 */
function createDefaultColorScale(): ColorScale {
  return {
    stops: [
      [0, 'rgba(0, 0, 0, 0)'],
      [1, 'rgba(255, 255, 255, 0.7)'],
      [100, 'rgba(255, 0, 0, 0.9)']
    ],
    domain: [0, 100],
    buckets: 10
  };
}

/**
 * Interpolate color between two RGB colors
 */
export function interpolateColor(
  color1: [number, number, number],
  color2: [number, number, number],
  factor: number
): [number, number, number] {
  const r = Math.round(color1[0] + factor * (color2[0] - color1[0]));
  const g = Math.round(color1[1] + factor * (color2[1] - color1[1]));
  const b = Math.round(color1[2] + factor * (color2[2] - color1[2]));
  return [r, g, b];
}

/**
 * Convert RGB to hex color
 */
export function rgbToHex(r: number, g: number, b: number): string {
  return `#${((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1)}`;
}

/**
 * Parse CSS color string to RGB values
 */
export function parseColor(colorString: string): [number, number, number] | null {
  const rgbaMatch = colorString.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*[\d.]+)?\)/);
  if (rgbaMatch) {
    return [
      parseInt(rgbaMatch[1]),
      parseInt(rgbaMatch[2]),
      parseInt(rgbaMatch[3])
    ];
  }
  
  const hexMatch = colorString.match(/^#([0-9a-f]{6})$/i);
  if (hexMatch) {
    const hex = hexMatch[1];
    return [
      parseInt(hex.slice(0, 2), 16),
      parseInt(hex.slice(2, 4), 16),
      parseInt(hex.slice(4, 6), 16)
    ];
  }
  
  return null;
}

/**
 * Format number for display in legend
 */
export function formatLegendValue(value: number, unit: string = 'g/ha'): string {
  if (value === 0) return '0';
  if (value < 0.01) return `< 0.01 ${unit}`;
  if (value < 1) return `${value.toFixed(2)} ${unit}`;
  if (value < 10) return `${value.toFixed(1)} ${unit}`;
  return `${Math.round(value)} ${unit}`;
}

/**
 * Data field mappings for different pesticide modes
 */
export const DATA_FIELD_MAPPINGS = {
  h3: {
    total: 'pesticide_belastning_per_ha',
    pfas: 'pfas_containing_active_ingredient_intensity_grams_per_ha',
    diquat: 'diquat_containing_active_ingredient_intensity_grams_per_ha',
    glyphosate: 'glyphosate_containing_active_ingredient_intensity_grams_per_ha'
  },
  kommune: {
    total: 'pesticide_belastning_per_ha',
    pfas: 'pfas_containing_active_ingredient_intensity_grams_per_ha',
    diquat: 'diquat_containing_active_ingredient_intensity_grams_per_ha',
    glyphosate: 'glyphosate_containing_active_ingredient_intensity_grams_per_ha'
  }
} as const;

/**
 * Get data field for a specific mode and layer type
 */
export function getDataField(
  mode: 'total' | 'pfas' | 'diquat' | 'glyphosate',
  layerType: 'h3' | 'kommune'
): string {
  return DATA_FIELD_MAPPINGS[layerType][mode];
} 