'use client';

import React, { useEffect, useState, useRef } from 'react';
import maplibregl from 'maplibre-gl';
import { LayerVisibility } from './NewPMTilesMap';
import { formatLegendValue } from '@/utils/color-utils';

export interface TooltipsProps {
  map: maplibregl.Map;
  layerVisibility: LayerVisibility;
  dataMode: 'total' | 'pfas' | 'diquat' | 'glyphosate';
  year: number;
}

interface TooltipData {
  x: number;
  y: number;
  visible: boolean;
  content: TooltipContent | null;
}

interface TooltipContent {
  type: 'h3' | 'kommune' | 'bnbo';
  properties: Record<string, any>;
}

interface DetailedPopupData {
  visible: boolean;
  content: TooltipContent | null;
  position: [number, number] | null;
}

/**
 * Tooltips component handles hover tooltips and click interactions for map features
 */
export function Tooltips({ 
  map, 
  layerVisibility, 
  dataMode, 
  year 
}: TooltipsProps) {
  const [tooltip, setTooltip] = useState<TooltipData>({
    x: 0,
    y: 0,
    visible: false,
    content: null
  });
  
  const [popup, setPopup] = useState<DetailedPopupData>({
    visible: false,
    content: null,
    position: null
  });

  const popupRef = useRef<maplibregl.Popup | null>(null);

  // Set up map event listeners
  useEffect(() => {
    const handleMouseMove = (e: maplibregl.MapMouseEvent) => {
      const features = map.queryRenderedFeatures(e.point);
      const relevantFeature = findRelevantFeature(features);

      if (relevantFeature) {
        setTooltip({
          x: e.point.x,
          y: e.point.y,
          visible: true,
          content: {
            type: getFeatureType(relevantFeature),
            properties: relevantFeature.properties || {}
          }
        });
        
        // Change cursor to pointer
        map.getCanvas().style.cursor = 'pointer';
      } else {
        setTooltip(prev => ({ ...prev, visible: false }));
        map.getCanvas().style.cursor = '';
      }
    };

    const handleClick = (e: maplibregl.MapMouseEvent) => {
      const features = map.queryRenderedFeatures(e.point);
      const relevantFeature = findRelevantFeature(features);

      if (relevantFeature) {
        const content = {
          type: getFeatureType(relevantFeature),
          properties: relevantFeature.properties || {}
        };

        // Create or update popup
        if (popupRef.current) {
          popupRef.current.remove();
        }

        popupRef.current = new maplibregl.Popup({
          closeButton: true,
          closeOnClick: false,
          maxWidth: '400px'
        })
          .setLngLat(e.lngLat)
          .setHTML(renderDetailedPopupContent(content, dataMode, year))
          .addTo(map);

        setPopup({
          visible: true,
          content,
          position: [e.lngLat.lng, e.lngLat.lat]
        });
      }
    };

    const handleMouseLeave = () => {
      setTooltip(prev => ({ ...prev, visible: false }));
      map.getCanvas().style.cursor = '';
    };

    // Add event listeners
    map.on('mousemove', handleMouseMove);
    map.on('click', handleClick);
    map.on('mouseleave', handleMouseLeave);

    return () => {
      map.off('mousemove', handleMouseMove);
      map.off('click', handleClick);
      map.off('mouseleave', handleMouseLeave);
      
      if (popupRef.current) {
        popupRef.current.remove();
        popupRef.current = null;
      }
    };
  }, [map, layerVisibility, dataMode, year]);

  // Find the most relevant feature based on current layer visibility
  const findRelevantFeature = (features: maplibregl.MapGeoJSONFeature[]) => {
    if (!features.length) return null;

    // Prioritize based on current visibility
    if (layerVisibility.bnbo) {
      const bnboFeature = features.find(f => 
        f.layer.id.includes('bnbo') || f.source === 'bnbo'
      );
      if (bnboFeature) return bnboFeature;
    }

    if (layerVisibility.h3) {
      const h3Feature = features.find(f => 
        f.layer.id.includes('h3') || f.source?.toString().includes('h3')
      );
      if (h3Feature) return h3Feature;
    }

    if (layerVisibility.kommune) {
      const kommuneFeature = features.find(f => 
        f.layer.id.includes('kommune') || f.source?.toString().includes('kommune')
      );
      if (kommuneFeature) return kommuneFeature;
    }

    return features[0];
  };

  // Determine feature type based on layer information
  const getFeatureType = (feature: maplibregl.MapGeoJSONFeature): 'h3' | 'kommune' | 'bnbo' => {
    if (feature.layer.id.includes('bnbo') || feature.source === 'bnbo') {
      return 'bnbo';
    }
    if (feature.layer.id.includes('h3') || feature.source?.toString().includes('h3')) {
      return 'h3';
    }
    return 'kommune';
  };

  // Render tooltip content based on feature type
  const renderTooltipContent = (content: TooltipContent) => {
    const { type, properties } = content;

    switch (type) {
      case 'h3':
        return renderH3Tooltip(properties, dataMode);
      case 'kommune':
        return renderKommuneTooltip(properties, dataMode);
      case 'bnbo':
        return renderBNBOTooltip(properties);
      default:
        return null;
    }
  };

  // Render H3 cell tooltip
  const renderH3Tooltip = (properties: Record<string, any>, mode: string) => {
    const getValue = (field: string) => {
      const value = properties[field];
      return value !== undefined && value !== null ? value : 'N/A';
    };

    const getIntensityField = () => {
      switch (mode) {
        case 'pfas': return 'pfas_containing_active_ingredient_intensity_grams_per_ha';
        case 'diquat': return 'diquat_containing_active_ingredient_intensity_grams_per_ha';
        case 'glyphosate': return 'glyphosate_containing_active_ingredient_intensity_grams_per_ha';
        default: return 'pesticide_belastning_per_ha';
      }
    };

    const intensityValue = getValue(getIntensityField());
    const formattedValue = typeof intensityValue === 'number' 
      ? formatLegendValue(intensityValue, 'g/ha')
      : intensityValue;

    return (
      <div className="bg-black/90 text-white p-3 rounded-lg text-sm max-w-xs">
        <div className="font-semibold mb-2">H3 Cell</div>
        <div className="space-y-1">
          <div><span className="text-gray-300">Cell ID:</span> {getValue('h3_cell')}</div>
          <div><span className="text-gray-300">Area:</span> {formatLegendValue(getValue('h3_cell_area_ha'), 'ha')}</div>
          <div><span className="text-gray-300">Fields:</span> {getValue('unique_field_count')}</div>
          <div><span className="text-gray-300">{mode.toUpperCase()} Intensity:</span> {formattedValue}</div>
          <div><span className="text-gray-300">Coverage:</span> {(getValue('actual_coverage_ratio') * 100).toFixed(1)}%</div>
        </div>
      </div>
    );
  };

  // Render Kommune tooltip
  const renderKommuneTooltip = (properties: Record<string, any>, mode: string) => {
    const getValue = (field: string) => {
      const value = properties[field];
      return value !== undefined && value !== null ? value : 'N/A';
    };

    const getIntensityField = () => {
      switch (mode) {
        case 'pfas': return 'pfas_containing_active_ingredient_intensity_grams_per_ha';
        case 'diquat': return 'diquat_containing_active_ingredient_intensity_grams_per_ha';
        case 'glyphosate': return 'glyphosate_containing_active_ingredient_intensity_grams_per_ha';
        default: return 'pesticide_belastning_per_ha';
      }
    };

    const intensityValue = getValue(getIntensityField());
    const formattedValue = typeof intensityValue === 'number' 
      ? formatLegendValue(intensityValue, 'g/ha')
      : intensityValue;

    return (
      <div className="bg-black/90 text-white p-3 rounded-lg text-sm max-w-xs">
        <div className="font-semibold mb-2">Kommune</div>
        <div className="space-y-1">
          <div><span className="text-gray-300">Name:</span> {getValue('kommune_name')}</div>
          <div><span className="text-gray-300">Code:</span> {getValue('kommune_code')}</div>
          <div><span className="text-gray-300">Agri. Area:</span> {formatLegendValue(getValue('total_agricultural_area_ha'), 'ha')}</div>
          <div><span className="text-gray-300">Fields:</span> {getValue('unique_field_count')}</div>
          <div><span className="text-gray-300">{mode.toUpperCase()} Intensity:</span> {formattedValue}</div>
        </div>
      </div>
    );
  };

  // Render BNBO tooltip
  const renderBNBOTooltip = (properties: Record<string, any>) => {
    const getValue = (field: string) => {
      const value = properties[field];
      return value !== undefined && value !== null ? value : 'N/A';
    };

    const getStatusText = (code: number) => {
      switch (code) {
        case 1: return 'Action Required';
        case 2: return 'Completed';
        case 3: return 'Unknown';
        default: return 'Unknown';
      }
    };

    const statusCode = getValue('status_code');
    const statusText = typeof statusCode === 'number' ? getStatusText(statusCode) : 'Unknown';

    return (
      <div className="bg-black/90 text-white p-3 rounded-lg text-sm max-w-xs">
        <div className="font-semibold mb-2">BNBO Protected Area</div>
        <div className="space-y-1">
          <div><span className="text-gray-300">ID:</span> {getValue('bnbo_id')}</div>
          <div><span className="text-gray-300">Status:</span> {statusText}</div>
          <div><span className="text-gray-300">Area:</span> {formatLegendValue(getValue('area_ha'), 'ha')}</div>
          <div><span className="text-gray-300">Description:</span> {getValue('description')}</div>
        </div>
      </div>
    );
  };

  return (
    <>
      {/* Hover tooltip */}
      {tooltip.visible && tooltip.content && (
        <div
          className="fixed pointer-events-none z-50"
          style={{
            left: tooltip.x + 10,
            top: tooltip.y - 10,
            transform: 'translateY(-100%)'
          }}
        >
          {renderTooltipContent(tooltip.content)}
        </div>
      )}
    </>
  );
}

// Helper function to render detailed popup content (used by MapLibre popup)
function renderDetailedPopupContent(
  content: TooltipContent,
  dataMode: string,
  year: number
): string {
  const { type, properties } = content;
  
  const getValue = (field: string) => {
    const value = properties[field];
    return value !== undefined && value !== null ? value : 'N/A';
  };

  switch (type) {
    case 'h3':
      return `
        <div class="p-4">
          <h3 class="text-lg font-bold mb-3">H3 Cell Details</h3>
          <div class="space-y-2 text-sm">
            <div><strong>Year:</strong> ${year}</div>
            <div><strong>Cell ID:</strong> ${getValue('h3_cell')}</div>
            <div><strong>Center:</strong> ${getValue('center_lat')?.toFixed(4)}, ${getValue('center_lon')?.toFixed(4)}</div>
            <div><strong>Cell Area:</strong> ${formatLegendValue(getValue('h3_cell_area_ha'), 'ha')}</div>
            <div><strong>Coverage Area:</strong> ${formatLegendValue(getValue('total_intersection_area_ha'), 'ha')}</div>
            <div><strong>Coverage Ratio:</strong> ${(getValue('actual_coverage_ratio') * 100).toFixed(1)}%</div>
            <div><strong>Unique Fields:</strong> ${getValue('unique_field_count')}</div>
            <div><strong>Crop Diversity:</strong> ${getValue('crop_diversity')}</div>
            <hr class="my-3">
            <div><strong>Total Pesticide:</strong> ${formatLegendValue(getValue('pesticide_belastning_per_ha'), 'g/ha')}</div>
            <div><strong>PFAS Intensity:</strong> ${formatLegendValue(getValue('pfas_containing_active_ingredient_intensity_grams_per_ha'), 'g/ha')}</div>
            <div><strong>Diquat Intensity:</strong> ${formatLegendValue(getValue('diquat_containing_active_ingredient_intensity_grams_per_ha'), 'g/ha')}</div>
            <div><strong>Glyphosate Intensity:</strong> ${formatLegendValue(getValue('glyphosate_containing_active_ingredient_intensity_grams_per_ha'), 'g/ha')}</div>
            <hr class="my-3">
            <div><strong>Total Applications:</strong> ${getValue('total_pesticide_applications')}</div>
            <div><strong>PFAS Applications:</strong> ${getValue('pfas_containing_applications')}</div>
            <div><strong>Diquat Applications:</strong> ${getValue('diquat_containing_applications')}</div>
            <div><strong>Glyphosate Applications:</strong> ${getValue('glyphosate_containing_applications')}</div>
          </div>
        </div>
      `;

    case 'kommune':
      return `
        <div class="p-4">
          <h3 class="text-lg font-bold mb-3">Kommune Details</h3>
          <div class="space-y-2 text-sm">
            <div><strong>Year:</strong> ${year}</div>
            <div><strong>Name:</strong> ${getValue('kommune_name')}</div>
            <div><strong>Code:</strong> ${getValue('kommune_code')}</div>
            <div><strong>Region:</strong> ${getValue('region_code')}</div>
            <div><strong>Total Area:</strong> ${formatLegendValue(getValue('kommune_area_ha'), 'ha')}</div>
            <div><strong>Agricultural Area:</strong> ${formatLegendValue(getValue('total_agricultural_area_ha'), 'ha')}</div>
            <div><strong>Agri. Coverage:</strong> ${getValue('agricultural_coverage_pct')?.toFixed(1)}%</div>
            <div><strong>Unique Fields:</strong> ${getValue('unique_field_count')}</div>
            <div><strong>Unique Companies:</strong> ${getValue('unique_company_count')}</div>
            <div><strong>Crop Diversity:</strong> ${getValue('crop_diversity')}</div>
            <hr class="my-3">
            <div><strong>Total Pesticide:</strong> ${formatLegendValue(getValue('pesticide_belastning_per_ha'), 'g/ha')}</div>
            <div><strong>PFAS Intensity:</strong> ${formatLegendValue(getValue('pfas_containing_active_ingredient_intensity_grams_per_ha'), 'g/ha')}</div>
            <div><strong>Diquat Intensity:</strong> ${formatLegendValue(getValue('diquat_containing_active_ingredient_intensity_grams_per_ha'), 'g/ha')}</div>
            <div><strong>Glyphosate Intensity:</strong> ${formatLegendValue(getValue('glyphosate_containing_active_ingredient_intensity_grams_per_ha'), 'g/ha')}</div>
            <hr class="my-3">
            <div><strong>Total Applications:</strong> ${getValue('total_pesticide_applications')}</div>
            <div><strong>PFAS Applications:</strong> ${getValue('pfas_containing_applications')}</div>
            <div><strong>Diquat Applications:</strong> ${getValue('diquat_containing_applications')}</div>
            <div><strong>Glyphosate Applications:</strong> ${getValue('glyphosate_containing_applications')}</div>
            <div><strong>Unique Products:</strong> ${getValue('unique_pesticide_products')}</div>
          </div>
        </div>
      `;

    case 'bnbo':
      const statusCode = getValue('status_code');
      const statusText = typeof statusCode === 'number' 
        ? (statusCode === 1 ? 'Action Required' : statusCode === 2 ? 'Completed' : 'Unknown')
        : 'Unknown';
      
      return `
        <div class="p-4">
          <h3 class="text-lg font-bold mb-3">BNBO Protected Area</h3>
          <div class="space-y-2 text-sm">
            <div><strong>ID:</strong> ${getValue('bnbo_id')}</div>
            <div><strong>Status:</strong> ${statusText}</div>
            <div><strong>Area:</strong> ${formatLegendValue(getValue('area_ha'), 'ha')}</div>
            <div><strong>Description:</strong> ${getValue('description')}</div>
            <div><strong>Designation Date:</strong> ${getValue('designation_date')}</div>
            <div><strong>Management Plan:</strong> ${getValue('management_plan') || 'N/A'}</div>
          </div>
        </div>
      `;

    default:
      return '<div class="p-4">No data available</div>';
  }
} 