import maplibregl from 'maplibre-gl';
import { PMTilesMetadata } from '@/services/pmtiles-discovery';
import { 
  createColorExpression, 
  getDataField, 
  createPesticideColorScale,
  createBNBOColorScale,
  calculateDataStats,
  type DataStats,
  type ColorScale 
} from '@/utils/color-utils';
import { LayerVisibility } from './NewPMTilesMap';

export interface LayerUpdateOptions {
  dataMode: 'total' | 'pfas' | 'diquat' | 'glyphosate';
  year: number;
  resolution: number;
}

/**
 * LayerManager handles all map layer operations including:
 * - Basemap initialization
 * - Zoom-based layer switching (Kommune vs H3)
 * - Data mode and year updates
 * - BNBO overlay management
 */
export class LayerManager {
  private map: maplibregl.Map;
  private currentLayers: Set<string> = new Set();
  private colorScales: Map<string, ColorScale> = new Map();
  private loadedSources: Set<string> = new Set();

  constructor(map: maplibregl.Map) {
    this.map = map;
  }

  /**
   * Initialize the basemap layer
   */
  async initializeBasemap(basemapMetadata: PMTilesMetadata): Promise<void> {
    const sourceId = 'basemap';
    const layerId = 'basemap-layer';

    // Convert GCS URL to HTTP URL
    const url = this.convertGCSUrl(basemapMetadata.url);

    // Add basemap source
    this.map.addSource(sourceId, {
      type: 'vector',
      url: `pmtiles://${url}`
    });

    // Add basemap layer
    this.map.addLayer({
      id: layerId,
      type: 'fill',
      source: sourceId,
      'source-layer': 'land', // Adjust based on actual basemap structure
      paint: {
        'fill-color': '#1a1a1a',
        'fill-opacity': 1
      }
    });

    this.currentLayers.add(layerId);
    this.loadedSources.add(sourceId);
  }

  /**
   * Update layer visibility based on zoom level
   */
  async updateLayerVisibility(
    visibility: LayerVisibility,
    options: LayerUpdateOptions
  ): Promise<void> {
    // Handle Kommune layer
    if (visibility.kommune) {
      await this.showKommuneLayer(options);
    } else {
      this.hideKommuneLayer();
    }

    // Handle H3 layer
    if (visibility.h3) {
      await this.showH3Layer(options);
    } else {
      this.hideH3Layer();
    }
  }

  /**
   * Show Kommune layer for low zoom levels
   */
  private async showKommuneLayer(options: LayerUpdateOptions): Promise<void> {
    const sourceId = `kommune-${options.year}`;
    const layerId = `kommune-layer-${options.year}`;

    // Remove existing Kommune layers
    this.hideKommuneLayer();

    try {
      // Mock Kommune data URL (in production, use actual discovery service)
      const url = `https://storage.googleapis.com/landbrugsdata-raw-data/gold/pmtiles/kommune_pfas_${options.year}/latest/kommune_pfas_${options.year}.pmtiles`;

      // Add source if not already loaded
      if (!this.loadedSources.has(sourceId)) {
        this.map.addSource(sourceId, {
          type: 'vector',
          url: `pmtiles://${url}`
        });
        this.loadedSources.add(sourceId);
      }

      // Create color scale for Kommune data
      const dataField = getDataField(options.dataMode, 'kommune');
      const colorScale = this.getOrCreateColorScale(`kommune-${options.dataMode}`, 'kommune');
      const colorExpression = createColorExpression(colorScale, dataField);

      // Add Kommune layer
      this.map.addLayer({
        id: layerId,
        type: 'fill',
        source: sourceId,
        'source-layer': 'kommune', // Adjust based on actual PMTiles structure
        paint: {
          'fill-color': colorExpression as any,
          'fill-opacity': 0.8,
          'fill-outline-color': '#ffffff'
        }
      });

      this.currentLayers.add(layerId);
    } catch (error) {
      console.error('Error showing Kommune layer:', error);
    }
  }

  /**
   * Hide Kommune layer
   */
  private hideKommuneLayer(): void {
    // Remove all Kommune layers
    for (const layerId of this.currentLayers) {
      if (layerId.startsWith('kommune-layer-')) {
        if (this.map.getLayer(layerId)) {
          this.map.removeLayer(layerId);
        }
        this.currentLayers.delete(layerId);
      }
    }
  }

  /**
   * Show H3 layer for high zoom levels
   */
  private async showH3Layer(options: LayerUpdateOptions): Promise<void> {
    const sourceId = `h3-${options.year}-res${options.resolution}`;
    const layerId = `h3-layer-${options.year}-res${options.resolution}`;

    // Remove existing H3 layers
    this.hideH3Layer();

    try {
      // Mock H3 data URL (in production, use actual discovery service)
      const url = `https://storage.googleapis.com/landbrugsdata-raw-data/gold/pmtiles/h3_pfas_${options.year}_res${options.resolution}/latest/h3_pfas_${options.year}_res${options.resolution}.pmtiles`;

      // Add source if not already loaded
      if (!this.loadedSources.has(sourceId)) {
        this.map.addSource(sourceId, {
          type: 'vector',
          url: `pmtiles://${url}`
        });
        this.loadedSources.add(sourceId);
      }

      // Create color scale for H3 data
      const dataField = getDataField(options.dataMode, 'h3');
      const colorScale = this.getOrCreateColorScale(`h3-${options.dataMode}`, 'h3');
      const colorExpression = createColorExpression(colorScale, dataField);

      // Add H3 layer
      this.map.addLayer({
        id: layerId,
        type: 'fill',
        source: sourceId,
        'source-layer': 'h3', // Adjust based on actual PMTiles structure
        paint: {
          'fill-color': colorExpression as any,
          'fill-opacity': 0.7
        }
      });

      this.currentLayers.add(layerId);
    } catch (error) {
      console.error('Error showing H3 layer:', error);
    }
  }

  /**
   * Hide H3 layer
   */
  private hideH3Layer(): void {
    // Remove all H3 layers
    for (const layerId of this.currentLayers) {
      if (layerId.startsWith('h3-layer-')) {
        if (this.map.getLayer(layerId)) {
          this.map.removeLayer(layerId);
        }
        this.currentLayers.delete(layerId);
      }
    }
  }

  /**
   * Update data mode (pesticide type) for current layers
   */
  async updateDataMode(
    mode: 'total' | 'pfas' | 'diquat' | 'glyphosate',
    options: Omit<LayerUpdateOptions, 'dataMode'>
  ): Promise<void> {
    const fullOptions = { ...options, dataMode: mode };

    // Update visible layers
    for (const layerId of this.currentLayers) {
      if (layerId.startsWith('kommune-layer-')) {
        const dataField = getDataField(mode, 'kommune');
        const colorScale = this.getOrCreateColorScale(`kommune-${mode}`, 'kommune');
        const colorExpression = createColorExpression(colorScale, dataField);

        this.map.setPaintProperty(layerId, 'fill-color', colorExpression);
      } else if (layerId.startsWith('h3-layer-')) {
        const dataField = getDataField(mode, 'h3');
        const colorScale = this.getOrCreateColorScale(`h3-${mode}`, 'h3');
        const colorExpression = createColorExpression(colorScale, dataField);

        this.map.setPaintProperty(layerId, 'fill-color', colorExpression);
      }
    }
  }

  /**
   * Update year for current layers
   */
  async updateYear(
    year: number,
    options: Omit<LayerUpdateOptions, 'year'>
  ): Promise<void> {
    const fullOptions = { ...options, year };

    // Determine which layers need to be updated
    const needsKommuneUpdate = Array.from(this.currentLayers).some(id => 
      id.startsWith('kommune-layer-')
    );
    const needsH3Update = Array.from(this.currentLayers).some(id => 
      id.startsWith('h3-layer-')
    );

    // Update layers with new year data
    if (needsKommuneUpdate) {
      await this.showKommuneLayer(fullOptions);
    }
    if (needsH3Update) {
      await this.showH3Layer(fullOptions);
    }
  }

  /**
   * Update BNBO layer visibility
   */
  updateBNBOVisibility(visible: boolean, bnboMetadata: PMTilesMetadata): void {
    const sourceId = 'bnbo';
    const layerId = 'bnbo-layer';

    if (visible) {
      // Add BNBO layer
      if (!this.loadedSources.has(sourceId)) {
        const url = this.convertGCSUrl(bnboMetadata.url);
        
        this.map.addSource(sourceId, {
          type: 'vector',
          url: `pmtiles://${url}`
        });
        this.loadedSources.add(sourceId);
      }

      if (!this.map.getLayer(layerId)) {
        const colorScale = createBNBOColorScale();
        const colorExpression = createColorExpression(colorScale, 'status_code');

        this.map.addLayer({
          id: layerId,
          type: 'fill',
          source: sourceId,
          'source-layer': 'bnbo', // Adjust based on actual PMTiles structure
          paint: {
            'fill-color': colorExpression as any,
            'fill-opacity': 0.6,
            'fill-outline-color': '#ffffff'
          }
        });

        this.currentLayers.add(layerId);
      }
    } else {
      // Remove BNBO layer
      if (this.map.getLayer(layerId)) {
        this.map.removeLayer(layerId);
        this.currentLayers.delete(layerId);
      }
    }
  }

  /**
   * Get or create color scale for a specific data mode and layer type
   */
  private getOrCreateColorScale(key: string, layerType: 'h3' | 'kommune'): ColorScale {
    if (this.colorScales.has(key)) {
      return this.colorScales.get(key)!;
    }

    // Create mock data statistics for color scale generation
    // In production, this would use actual data statistics
    const mockStats: DataStats = {
      min: 0,
      max: layerType === 'h3' ? 100 : 50, // H3 typically has higher values
      mean: layerType === 'h3' ? 25 : 15,
      median: layerType === 'h3' ? 20 : 12,
      percentiles: {
        10: 1,
        20: 3,
        30: 5,
        40: 8,
        50: layerType === 'h3' ? 20 : 12,
        60: layerType === 'h3' ? 30 : 18,
        70: layerType === 'h3' ? 45 : 25,
        80: layerType === 'h3' ? 65 : 35,
        90: layerType === 'h3' ? 85 : 45
      },
      nonZeroMin: 0.1,
      nonZeroMax: layerType === 'h3' ? 100 : 50
    };

    const colorScale = createPesticideColorScale(mockStats);
    this.colorScales.set(key, colorScale);
    return colorScale;
  }

  /**
   * Convert GCS URL to HTTP URL for PMTiles access
   */
  private convertGCSUrl(gcsUrl: string): string {
    if (gcsUrl.startsWith('gs://')) {
      return gcsUrl.replace('gs://', 'https://storage.googleapis.com/');
    }
    return gcsUrl;
  }

  /**
   * Get current layer IDs
   */
  getCurrentLayers(): string[] {
    return Array.from(this.currentLayers);
  }

  /**
   * Clean up resources
   */
  dispose(): void {
    // Remove all layers
    for (const layerId of this.currentLayers) {
      if (this.map.getLayer(layerId)) {
        this.map.removeLayer(layerId);
      }
    }

    // Remove all sources
    for (const sourceId of this.loadedSources) {
      if (this.map.getSource(sourceId)) {
        this.map.removeSource(sourceId);
      }
    }

    this.currentLayers.clear();
    this.loadedSources.clear();
    this.colorScales.clear();
  }
} 